[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Global Economy in the Shadow of War - Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --imf-blue: #002244;
    --imf-blue-light: #003366;
    --imf-blue-pale: #e8eef4;
    --gray-100: #f5f6f8;
    --gray-200: #e2e5ea;
    --gray-300: #c8cdd5;
    --gray-500: #6b7280;
    --gray-700: #374151;
    --gray-900: #111827;
    --amber: #d97706;
    --amber-light: #fef3c7;
    --amber-dark: #92400e;
    --burnt-orange: #c2410c;
    --red-subtle: #fef2f2;
  }

  body {
    width: 2384px;
    height: 3370px;
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    background: #ffffff;
    color: var(--gray-900);
    overflow: hidden;
  }

  .poster {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    padding: 60px 70px;
    gap: 0;
  }

  /* === HEADER === */
  .header {
    background: linear-gradient(135deg, var(--imf-blue) 0%, var(--imf-blue-light) 100%);
    color: white;
    padding: 60px 70px;
    border-radius: 12px;
    margin-bottom: 40px;
    position: relative;
    overflow: hidden;
  }
  .header::after {
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 350px; height: 350px;
    background: rgba(255,255,255,0.03);
    border-radius: 50%;
  }
  .header .venue {
    font-size: 22px;
    font-weight: 500;
    letter-spacing: 3px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 20px;
  }
  .header h1 {
    font-size: 62px;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 18px;
    max-width: 1800px;
  }
  .header .subtitle {
    font-size: 26px;
    font-weight: 300;
    opacity: 0.85;
    line-height: 1.5;
    max-width: 1700px;
  }

  /* === METRICS BAR === */
  .metrics-bar {
    display: flex;
    gap: 24px;
    margin-bottom: 40px;
  }
  .metric-card {
    flex: 1;
    background: var(--gray-100);
    border-radius: 10px;
    padding: 28px 32px;
    border-left: 5px solid var(--imf-blue);
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .metric-card.warning {
    border-left-color: var(--amber);
    background: var(--amber-light);
  }
  .metric-card .metric-value {
    font-size: 42px;
    font-weight: 800;
    color: var(--imf-blue);
  }
  .metric-card.warning .metric-value {
    color: var(--amber-dark);
  }
  .metric-card .metric-label {
    font-size: 18px;
    font-weight: 500;
    color: var(--gray-500);
  }
  .metric-card .metric-source {
    font-size: 14px;
    color: var(--gray-300);
  }

  /* === CONTENT GRID === */
  .content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
    gap: 36px;
    flex: 1;
  }

  .section {
    background: white;
    border: 1.5px solid var(--gray-200);
    border-radius: 10px;
    padding: 40px;
    position: relative;
  }
  .section.full-width {
    grid-column: 1 / -1;
  }
  .section-label {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: var(--imf-blue);
    margin-bottom: 10px;
    opacity: 0.6;
  }
  .section h2 {
    font-size: 32px;
    font-weight: 700;
    color: var(--imf-blue);
    margin-bottom: 20px;
    line-height: 1.25;
  }

  /* === GROWTH TABLE === */
  .growth-chart-area {
    width: 100%;
  }
  .growth-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 19px;
    margin-bottom: 24px;
  }
  .growth-table thead th {
    background: var(--imf-blue);
    color: white;
    padding: 14px 16px;
    text-align: center;
    font-weight: 600;
    font-size: 17px;
  }
  .growth-table thead th:first-child {
    text-align: left;
    border-radius: 8px 0 0 0;
  }
  .growth-table thead th:last-child {
    border-radius: 0 8px 0 0;
  }
  .growth-table tbody td {
    padding: 13px 16px;
    text-align: center;
    border-bottom: 1px solid var(--gray-200);
  }
  .growth-table tbody td:first-child {
    text-align: left;
    font-weight: 600;
    color: var(--imf-blue-light);
    font-size: 17px;
  }
  .growth-table tbody tr:nth-child(even) {
    background: var(--gray-100);
  }
  .growth-table .val {
    font-weight: 700;
    color: var(--imf-blue);
  }
  .growth-table .slow {
    color: var(--burnt-orange);
    font-weight: 600;
    font-style: italic;
  }
  .growth-band-note {
    display: flex;
    align-items: center;
    gap: 16px;
    background: var(--imf-blue-pale);
    padding: 18px 24px;
    border-radius: 8px;
    font-size: 19px;
  }
  .growth-band-note .band {
    font-size: 36px;
    font-weight: 800;
    color: var(--imf-blue);
    white-space: nowrap;
  }
  .growth-band-note .band-text {
    color: var(--gray-700);
    line-height: 1.45;
  }
  .growth-band-note .band-text strong {
    color: var(--burnt-orange);
  }

  /* === RISK CALLOUT === */
  .risk-callout {
    background: linear-gradient(135deg, #7c2d12 0%, #92400e 100%);
    color: white;
    padding: 36px 44px;
    border-radius: 10px;
    margin-bottom: 28px;
    position: relative;
    overflow: hidden;
  }
  .risk-callout::before {
    content: '⚠';
    position: absolute;
    right: 30px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 90px;
    opacity: 0.12;
  }
  .risk-callout .risk-label {
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 10px;
  }
  .risk-callout .risk-title {
    font-size: 34px;
    font-weight: 800;
    margin-bottom: 8px;
  }
  .risk-callout .risk-sub {
    font-size: 19px;
    opacity: 0.85;
    font-weight: 300;
  }

  /* === RISK LIST === */
  .risk-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 18px;
  }
  .risk-list li {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }
  .risk-icon {
    width: 44px;
    height: 44px;
    min-width: 44px;
    background: var(--amber-light);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
  }
  .risk-content h4 {
    font-size: 20px;
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 4px;
  }
  .risk-content p {
    font-size: 17px;
    color: var(--gray-500);
    line-height: 1.45;
  }

  /* === INFLATION === */
  .inflation-points {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .inflation-point {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 16px 20px;
    background: var(--gray-100);
    border-radius: 8px;
  }
  .inflation-point .dot {
    width: 10px;
    height: 10px;
    min-width: 10px;
    border-radius: 50%;
    margin-top: 7px;
  }
  .inflation-point .dot.blue { background: var(--imf-blue); }
  .inflation-point .dot.amber { background: var(--amber); }
  .inflation-point .dot.orange { background: var(--burnt-orange); }
  .inflation-point .ip-text {
    font-size: 18px;
    line-height: 1.5;
    color: var(--gray-700);
  }
  .inflation-point .ip-text strong {
    color: var(--gray-900);
  }

  /* === POLICY TIMELINE === */
  .policy-timeline {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
    padding-left: 30px;
  }
  .policy-timeline::before {
    content: '';
    position: absolute;
    left: 9px;
    top: 10px;
    bottom: 10px;
    width: 3px;
    background: linear-gradient(to bottom, var(--imf-blue), var(--amber));
    border-radius: 2px;
  }
  .policy-step {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    padding: 14px 0;
    position: relative;
  }
  .policy-step::before {
    content: '';
    position: absolute;
    left: -26px;
    top: 22px;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: var(--imf-blue);
    border: 3px solid white;
    box-shadow: 0 0 0 2px var(--imf-blue);
  }
  .policy-step:nth-child(4)::before,
  .policy-step:nth-child(5)::before,
  .policy-step:nth-child(6)::before {
    background: var(--amber);
    box-shadow: 0 0 0 2px var(--amber);
  }
  .policy-period {
    font-size: 16px;
    font-weight: 700;
    color: var(--imf-blue);
    min-width: 120px;
    padding-top: 2px;
  }
  .policy-step:nth-child(n+4) .policy-period {
    color: var(--amber-dark);
  }
  .policy-desc {
    font-size: 18px;
    color: var(--gray-700);
    line-height: 1.45;
  }

  /* === THEMES === */
  .themes-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }
  .theme-card {
    padding: 22px 24px;
    background: var(--gray-100);
    border-radius: 8px;
    border-left: 4px solid var(--imf-blue);
  }
  .theme-card h4 {
    font-size: 18px;
    font-weight: 700;
    color: var(--imf-blue);
    margin-bottom: 6px;
  }
  .theme-card p {
    font-size: 16px;
    color: var(--gray-500);
    line-height: 1.45;
  }

  /* === FOOTER === */
  .footer {
    margin-top: 36px;
    padding-top: 24px;
    border-top: 2px solid var(--gray-200);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 16px;
    color: var(--gray-500);
  }
  .footer .source {
    font-weight: 500;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="venue">IMF–World Bank Annual Meetings Research Symposium</div>
    <h1>Global Economy in the Shadow of War</h1>
    <div class="subtitle">IMF World Economic Outlook Trends 2024–2026 — A synthesis of eight WEO editions tracking global growth, inflation dynamics, and evolving policy priorities amid rising geopolitical uncertainty.</div>
  </div>

  <!-- KEY METRICS -->
  <div class="metrics-bar">
    <div class="metric-card">
      <div class="metric-value">3.0%</div>
      <div class="metric-label">Global Growth 2025 (proj.)</div>
      <div class="metric-source">WEO July 2025</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">3.3%</div>
      <div class="metric-label">Global Growth 2026 (proj.)</div>
      <div class="metric-source">WEO January 2026</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">3.2%</div>
      <div class="metric-label">Global Growth 2027 (proj.)</div>
      <div class="metric-source">WEO January 2026</div>
    </div>
    <div class="metric-card">
      <div class="metric-value">8</div>
      <div class="metric-label">WEO Editions Reviewed</div>
      <div class="metric-source">Jul 2024 – Apr 2026</div>
    </div>
    <div class="metric-card warning">
      <div class="metric-value">Downside</div>
      <div class="metric-label">Risk Balance — All 8 Editions</div>
      <div class="metric-source">Consistent finding</div>
    </div>
  </div>

  <!-- CONTENT -->
  <div class="content">

    <!-- GROWTH TRAJECTORY (full width) -->
    <div class="section full-width">
      <div class="section-label">Section 1</div>
      <h2>Global Growth Projections: A Narrow Band of Mediocrity</h2>
      <div class="growth-chart-area">
        <table class="growth-table">
          <thead>
            <tr>
              <th>WEO Edition</th>
              <th>Date</th>
              <th>2024</th>
              <th>2025</th>
              <th>2026</th>
              <th>2027</th>
            </tr>
          </thead>
          <tbody>
            <tr><td>Sticky Spot Update</td><td>Jul 2024</td><td class="val">3.2%</td><td class="val">3.3%</td><td>—</td><td>—</td></tr>
            <tr><td>Policy Pivot, Rising Threats</td><td>Oct 2024</td><td class="val">~3.2%</td><td class="val">~3.3%</td><td>—</td><td>—</td></tr>
            <tr><td>Divergent and Uncertain</td><td>Jan 2025</td><td>—</td><td class="val">3.3%</td><td class="val">3.3%</td><td>—</td></tr>
            <tr><td>Critical Juncture</td><td>Apr 2025</td><td>—</td><td class="slow">Slowing</td><td class="slow">Slowing</td><td>—</td></tr>
            <tr><td>Tenuous Resilience</td><td>Jul 2025</td><td>—</td><td class="val">3.0%</td><td class="val">3.1%</td><td>—</td></tr>
            <tr><td>Flux, Prospects Dim</td><td>Oct 2025</td><td>—</td><td class="slow">Slowing</td><td class="slow">Slowing</td><td>—</td></tr>
            <tr><td>Steady amid Divergent Forces</td><td>Jan 2026</td><td>—</td><td class="val">3.3%</td><td class="val">3.2%</td><td class="val">3.2%</td></tr>
            <tr><td>Shadow of War</td><td>Apr 2026</td><td>—</td><td class="slow">Slowing</td><td class="slow">Renewed pressure</td><td>—</td></tr>
          </tbody>
        </table>
        <div class="growth-band-note">
          <div class="band">3.0–3.3%</div>
          <div class="band-text">Global growth has hovered in this narrow band across all eight editions — well below the <strong>pre-pandemic average of ~3.8%</strong>. The economy isn't collapsing, but it isn't recovering either.</div>
        </div>
      </div>
    </div>

    <!-- DOWNSIDE RISKS -->
    <div class="section">
      <div class="section-label">Section 2</div>
      <h2>Dominant Downside Risks</h2>

      <div class="risk-callout">
        <div class="risk-label">Persistent Finding</div>
        <div class="risk-title">"Tilted to the Downside"</div>
        <div class="risk-sub">Across all eight WEO editions, the IMF consistently flagged the balance of risks as tilted to the downside.</div>
      </div>

      <ul class="risk-list">
        <li>
          <div class="risk-icon">📉</div>
          <div class="risk-content">
            <h4>Trade Policy Escalation</h4>
            <p>Tariff increases and retaliatory measures, especially from 2025 onward, with front-loading of activity temporarily masking damage.</p>
          </div>
        </li>
        <li>
          <div class="risk-icon">🌍</div>
          <div class="risk-content">
            <h4>Geopolitical Tensions</h4>
            <p>Conflicts in the Middle East, broader security concerns, and the war referenced in the April 2026 title.</p>
          </div>
        </li>
        <li>
          <div class="risk-icon">💻</div>
          <div class="risk-content">
            <h4>Technology Re-evaluation</h4>
            <p>Risk that elevated expectations around AI and tech investment could face a correction.</p>
          </div>
        </li>
        <li>
          <div class="risk-icon">🔥</div>
          <div class="risk-content">
            <h4>Persistent Services Inflation</h4>
            <p>Particularly in the US, where inflation returns to target more gradually than in other advanced economies.</p>
          </div>
        </li>
      </ul>
    </div>

    <!-- INFLATION DYNAMICS -->
    <div class="section">
      <div class="section-label">Section 3</div>
      <h2>Inflation Outlook &amp; Monetary Policy</h2>

      <div class="inflation-points">
        <div class="inflation-point">
          <div class="dot blue"></div>
          <div class="ip-text"><strong>Global headline inflation</strong> is on a declining trajectory, enabling central banks to begin easing — the October 2024 "policy pivot."</div>
        </div>
        <div class="inflation-point">
          <div class="dot amber"></div>
          <div class="ip-text"><strong>US inflation</strong> is projected to remain above target longer than in peer economies, complicating the Fed's easing path.</div>
        </div>
        <div class="inflation-point">
          <div class="dot orange"></div>
