om: 8px;\n  }\n  .risk-callout .risk-sub {\n    font-size: 19px;\n    opacity: 0.85;\n    font-weight: 300;\n  }\n\n  /* === RISK LIST === */\n  .risk-list {\n    list-style: none;\n    display: flex;\n    flex-direction: column;\n    gap: 18px;\n  }\n  .risk-list li {\n    display: flex;\n    gap: 16px;\n    align-items: flex-start;\n  }\n  .risk-icon {\n    width: 44px;\n    height: 44px;\n    min-width: 44px;\n    background: var(--amber-light);\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 22px;\n  }\n  .risk-content h4 {\n    font-size: 20px;\n    font-weight: 700;\n    color: var(--gray-900);\n    margin-bottom: 4px;\n  }\n  .risk-content p {\n    font-size: 17px;\n    color: var(--gray-500);\n    line-height: 1.45;\n  }\n\n  /* === INFLATION === */\n  .inflation-points {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n  }\n  .inflation-point {\n    display: flex;\n    align-items: flex-start;\n    gap: 14px;\n    padding: 16px 20px;\n    background: var(--gray-100);\n    border-radius: 8px;\n  }\n  .inflation-point .dot {\n    width: 10px;\n    height: 10px;\n    min-width: 10px;\n    border-radius: 50%;\n    margin-top: 7px;\n  }\n  .inflation-point .dot.blue { background: var(--imf-blue); }\n  .inflation-point .dot.amber { background: var(--amber); }\n  .inflation-point .dot.orange { background: var(--burnt-orange); }\n  .inflation-point .ip-text {\n    font-size: 18px;\n    line-height: 1.5;\n    color: var(--gray-700);\n  }\n  .inflation-point .ip-text strong {\n    color: var(--gray-900);\n  }\n\n  /* === POLICY TIMELINE === */\n  .policy-timeline {\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n    position: relative;\n    padding-left: 30px;\n  }\n  .policy-timeline::before {\n    content: '';\n    position: absolute;\n    left: 9px;\n    top: 10px;\n    bottom: 10px;\n    width: 3px;\n    background: linear-gradient(to bottom, var(--imf-blue), var(